package moe.crx.overport.pfdmr;
import java.nio.file.*;import java.util.*;import java.util.zip.*;import com.android.apksig.ApkVerifier;import com.reandroid.json.*;
import moe.crx.overport.patching.*;import moe.crx.overport.patches.ReplaceIconLabelPatchKt;import moe.crx.overport.app.SkiaIconResizer;
public class RedMatterActualApkTests {
 static int n;static void check(boolean b,String s){if(!b)throw new AssertionError(s);System.out.println("PASS "+s);n++;}
 static byte[] engine(Path apk)throws Exception{try(var zip=new ZipFile(apk.toFile())){return zip.getInputStream(zip.getEntry("lib/arm64-v8a/libUE4.so")).readAllBytes();}}
 public static void main(String[] args)throws Exception{
  Path run=Path.of(args[0]),input=Path.of(args[1]);String originalApkHash=UpdateFiles.sha256(input);byte[] before=engine(input);check(StereoPatch.sha256(before).equals(RedMatterSignerPatch.ORIGINAL),"actual Quest backup matches exact supported engine");int offset=RedMatterSignerPatch.offset(before,RedMatterSignerPatch.SITE);
  ReplaceIconLabelPatchKt.setPLATFORM_ICON_RESIZER(SkiaIconResizer.INSTANCE);System.setProperty("overport.iconCache",Path.of("app_icon").toAbsolutePath().toString());
  var c=new PatcherContext("3.4.3-aa54c3f",run.resolve("cache").toFile(),input.getFileName().toString(),"{filename}.{ext}");try(var in=Files.newInputStream(input)){c.prepare(in);}check(c.appVersionCode().equals("38")&&c.appVersionName().equals("1.0.013"),"actual Red Matter 1 version verified");
  Map<String,List<String>> selected=new LinkedHashMap<>();for(var patch:PatchStore.INSTANCE.recommended())selected.put(patch.getName(),List.of());selected.put(RedMatterSignerPatch.ID,List.of());
  c.patch(selected,(i,p)->{System.out.println("PATCH "+p.getName());return kotlin.Unit.INSTANCE;});Path ws=c.getWorkingDir().toPath();JSONObject config=new JSONObject(Files.readString(ws.resolve("root/lib/arm64-v8a/liboverport.config.so")));check(config.getInt("suggested_texture_width")==1800&&config.getInt("suggested_texture_height")==1664,"default conversion plus profile includes render size");
  byte[] certA=c.outputSignerCertificate();Path output=run.resolve("Red-Matter-beta13-test.apk");c.exportAndClose(Files.newOutputStream(output));var verified=new ApkVerifier.Builder(output.toFile()).build().verify();check(verified.isVerified()&&Arrays.equals(certA,verified.getSignerCertificates().get(0).getEncoded()),"real output APK verifies with exact pinned signer");byte[] after=engine(output);int changes=0;for(int i=0;i<before.length;i++)if(before[i]!=after[i]){changes++;if(i<offset||i>=offset+8)throw new AssertionError("Unexpected engine edit "+i);}check(changes>0&&after.length==before.length,"only the eight signer-load bytes can differ in real engine");
  try(var a=new ZipFile(input.toFile());var b=new ZipFile(output.toFile())){for(var entries=a.entries();entries.hasMoreElements();){var entry=entries.nextElement();if(entry.getName().startsWith("assets/")&&!entry.isDirectory()){var other=b.getEntry(entry.getName());if(other==null||!Arrays.equals(a.getInputStream(entry).readAllBytes(),b.getInputStream(other).readAllBytes()))throw new AssertionError("Game asset changed: "+entry.getName());}}}check(true,"all original game assets byte-identical");
  String firstHash=StereoPatch.sha256(after);before=null;after=null;c.cleanup();try(var in=Files.newInputStream(output)){c.prepare(in);}c.patch(Map.of(RedMatterSignerPatch.ID,List.of()),(i,p)->kotlin.Unit.INSTANCE);check(StereoPatch.sha256(Files.readAllBytes(ws.resolve(RedMatterSignerPatch.GAME))).equals(firstHash),"real same-key signed reimport and reapply stable");c.patch(Map.of(),(i,p)->kotlin.Unit.INSTANCE);check(StereoPatch.sha256(Files.readAllBytes(ws.resolve(RedMatterSignerPatch.GAME))).equals(RedMatterSignerPatch.ORIGINAL)&&!RedMatterSignerPatch.active(ws),"real deselection restores exact original engine");c.cleanup();
  var rekey=new PatcherContext("3.4.3-aa54c3f",run.resolve("rekey-cache").toFile(),"RedMatter.apk","{filename}.{ext}");try(var in=Files.newInputStream(output)){rekey.prepare(in);}rekey.patch(Map.of(RedMatterSignerPatch.ID,List.of()),(i,p)->kotlin.Unit.INSTANCE);byte[] certB=rekey.outputSignerCertificate();check(!Arrays.equals(certA,certB),"fresh per-package key changes target certificate");Path second=run.resolve("Red-Matter-beta13-rekey-test.apk");rekey.exportAndClose(Files.newOutputStream(second));check(new ApkVerifier.Builder(second.toFile()).build().verify().isVerified(),"actual engine rekey export passes final certificate and instruction checks");rekey.cleanup();
  check(UpdateFiles.sha256(input).equals(originalApkHash),"original Quest backup APK unchanged");System.out.println("ALL "+n+" ACTUAL RED MATTER APK CHECKS PASSED; no headset install or launch");
 }
}
